    "body": "<!doctype html>\n<html lang=\"en\">\n  <head>\n    <meta charset=\"utf-8\" />\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1\" />\n    <title>Recall Guardian · Alexa+ simulator</title>\n    <link rel=\"stylesheet\" href=\"/styles.css\" />\n  </head>\n  <body>\n    <header class=\"top\">\n      <div class=\"brand\">\n        <span class=\"ring\" id=\"ring\" aria-hidden=\"true\"></span>\n        <div>\n          <h1>Alexa+ <span class=\"tag\">simulator</span></h1>\n          <p>Recall Guardian · talking to a real MCP server</p>\n        </div>\n      </div>\n      <div class=\"controls\">\n        <label class=\"switch\" title=\"Hear Alexa's replies\">\n          <input id=\"speak-toggle\" type=\"checkbox\" checked />\n          <span>Speak replies</span>\n        </label>\n        <button id=\"demo-seed\" type=\"button\" class=\"ghost\" hidden>Load sample family</button>\n        <button id=\"demo-recall\" type=\"button\" class=\"ghost\" hidden>Simulate new recall</button>\n        <button id=\"reset\" type=\"button\" class=\"ghost\">Reset demo</button>\n      </div>\n    </header>\n\n    <main class=\"layout\">\n      <section class=\"chat\" aria-label=\"Conversation\">\n        <ol id=\"transcript\" class=\"transcript\" aria-live=\"polite\">\n          <li class=\"bubble alexa\">\n            Hi, I'm Alexa. Tell me about something your family owns, like a car seat or a heater,\n            and I'll watch for recalls.\n          </li>\n        </ol>\n        <p id=\"status\" class=\"status\" aria-live=\"polite\"></p>\n        <form id=\"composer\" class=\"composer\" autocomplete=\"off\">\n          <button\n            id=\"mic\"\n            type=\"button\"\n            class=\"mic\"\n            aria-pressed=\"false\"\n            aria-label=\"Talk to Alexa\"\n            title=\"Talk to Alexa\"\n          >\n            <svg viewBox=\"0 0 24 24\" width=\"22\" height=\"22\" aria-hidden=\"true\">\n              <path\n                fill=\"currentColor\"\n                d=\"M12 15a4 4 0 0 0 4-4V6a4 4 0 0 0-8 0v5a4 4 0 0 0 4 4Zm6-4a6 6 0 0 1-12 0H4a8 8 0 0 0 7 7.94V22h2v-3.06A8 8 0 0 0 20 11h-2Z\"\n              />\n            </svg>\n          </button>\n          <label class=\"sr-only\" for=\"message\">Message</label>\n          <input\n            id=\"message\"\n            name=\"message\"\n            type=\"text\"\n            placeholder=\"Talk, or type what you'd say to Alexa…\"\n            maxlength=\"500\"\n          />\n          <button id=\"send\" type=\"submit\">Send</button>\n        </form>\n      </section>\n\n      <aside class=\"side\">\n        <section class=\"panel\" aria-labelledby=\"inv-title\">\n          <h2 id=\"inv-title\">Your household</h2>\n          <ul id=\"inventory\" class=\"inventory\">\n            <li class=\"empty\">Nothing registered yet.</li>\n          </ul>\n        </section>\n        <section class=\"panel\" aria-labelledby=\"alerts-title\">\n          <h2 id=\"alerts-title\">Alerts</h2>\n          <ul id=\"alerts\" class=\"inventory\">\n            <li class=\"empty\">No alerts.</li>\n          </ul>\n        </section>\n      </aside>\n    </main>\n    <script src=\"/app.js\" type=\"module\"></script>\n  </body>\n</html>\n"
