  "/styles.css": {
    "contentType": "text/css; charset=utf-8",
    "body": ":root {\n  --bg: #0b1220;\n  --panel: #131c2e;\n  --line: #243049;\n  --text: #e8eef9;\n  --muted: #93a1bd;\n  --accent: #19c3ff;\n  --user: #1d4ed8;\n  --alert: #ffb020;\n  --danger: #ff5d6c;\n  color-scheme: dark;\n}\n\n* {\n  box-sizing: border-box;\n}\n\nbody {\n  margin: 0;\n  background: radial-gradient(1200px 600px at 20% -10%, #14305a 0%, var(--bg) 60%);\n  color: var(--text);\n  font:\n    16px/1.5 system-ui,\n    -apple-system,\n    'Segoe UI',\n    Roboto,\n    sans-serif;\n  min-height: 100vh;\n}\n\n.sr-only {\n  position: absolute;\n  width: 1px;\n  height: 1px;\n  overflow: hidden;\n  clip: rect(0 0 0 0);\n}\n\n[hidden] {\n  display: none !important;\n}\n\n.top {\n  display: flex;\n  justify-content: space-between;\n  align-items: center;\n  gap: 12px;\n  flex-wrap: wrap;\n  padding: 16px 24px;\n  border-bottom: 1px solid var(--line);\n}\n\n.brand {\n  display: flex;\n  gap: 14px;\n  align-items: center;\n}\n\n.brand h1 {\n  margin: 0;\n  font-size: 1.25rem;\n}\n\n.brand p {\n  margin: 0;\n  color: var(--muted);\n  font-size: 0.85rem;\n}\n\n.controls {\n  display: flex;\n  gap: 10px;\n  align-items: center;\n  flex-wrap: wrap;\n}\n\n.switch {\n  display: inline-flex;\n  align-items: center;\n  gap: 8px;\n  color: var(--muted);\n  font-size: 0.9rem;\n  cursor: pointer;\n}\n\n.switch input {\n  accent-color: var(--accent);\n  width: 18px;\n  height: 18px;\n}\n\n.tag {\n  font-size: 0.7rem;\n  font-weight: 600;\n  letter-spacing: 0.06em;\n  text-transform: uppercase;\n  color: var(--accent);\n  border: 1px solid var(--accent);\n  border-radius: 999px;\n  padding: 1px 8px;\n  vertical-align: middle;\n}\n\n.ring {\n  width: 38px;\n  height: 38px;\n  border-radius: 50%;\n  border: 5px solid var(--accent);\n  box-shadow:\n    0 0 18px rgba(25, 195, 255, 0.6),\n    inset 0 0 10px rgba(25, 195, 255, 0.4);\n  transition: border-color 0.2s;\n}\n\n.ring.busy,\n.ring.speaking {\n  animation: pulse 1s ease-in-out infinite;\n}\n\n.ring.listening {\n  border-color: #7cf0c6;\n  animation: pulse 0.7s ease-in-out infinite;\n}\n\n@keyframes pulse {\n  50% {\n    box-shadow:\n      0 0 30px rgba(25, 195, 255, 0.95),\n      inset 0 0 16px rgba(25, 195, 255, 0.7);\n  }\n}\n\n@media (prefers-reduced-motion: reduce) {\n  .ring.busy,\n  .ring.speaking,\n  .ring.listening {\n    animation: none;\n  }\n}\n\n.layout {\n  display: grid;\n  grid-template-columns: minmax(0, 1fr) 320px;\n  gap: 20px;\n  max-width: 1100px;\n  margin: 0 auto;\n  padding: 20px 16px 32px;\n}\n\n.chat,\n.panel {\n  background: var(--panel);\n  border: 1px solid var(--line);\n  border-radius: 16px;\n}\n\n.chat {\n  display: flex;\n  flex-direction: column;\n  height: min(72vh, 720px);\n}\n\n.transcript {\n  list-style: none;\n  margin: 0;\n  padding: 16px;\n  overflow-y: auto;\n  flex: 1;\n  display: flex;\n  flex-direction: column;\n  gap: 10px;\n}\n\n.bubble {\n  max-width: 82%;\n  padding: 10px 14px;\n  border-radius: 16px;\n}\n\n.bubble.alexa {\n  background: #1a2640;\n  border: 1px solid var(--line);\n  align-self: flex-start;\n  border-bottom-left-radius: 4px;\n}\n\n.bubble.proactive {\n  border-color: var(--alert);\n  box-shadow: 0 0 0 1px rgba(255, 176, 32, 0.25);\n}\n\n.bubble.proactive::before {\n  content: 'Alexa noticed something';\n  display: block;\n  font-size: 0.72rem;\n  font-weight: 600;\n  letter-spacing: 0.06em;\n  text-transform: uppercase;\n  color: var(--alert);\n  margin-bottom: 2px;\n}\n\n.bubble.user {\n  background: var(--user);\n  align-self: flex-end;\n  border-bottom-right-radius: 4px;\n}\n\n.bubble.error {\n  background: #3a1620;\n  border: 1px solid #7a2b3b;\n  align-self: flex-start;\n}\n\n.tools {\n  margin-top: 6px;\n  display: flex;\n  flex-wrap: wrap;\n  gap: 6px;\n}\n\n.chip {\n  font:\n    12px/1.4 ui-monospace,\n    Consolas,\n    monospace;\n  color: var(--accent);\n  background: rgba(25, 195, 255, 0.1);\n  border: 1px solid rgba(25, 195, 255, 0.35);\n  border-radius: 999px;\n  padding: 1px 8px;\n}\n\n.status {\n  min-height: 1.4em;\n  margin: 0;\n  padding: 0 16px;\n  color: var(--muted);\n  font-size: 0.85rem;\n}\n\n.composer {\n  display: flex;\n  gap: 8px;\n  padding: 12px;\n  border-top: 1px solid var(--line);\n}\n\n.composer input {\n  flex: 1;\n  min-width: 0;\n  background: #0e1626;\n  color: var(--text);\n  border: 1px solid var(--line);\n  border-radius: 999px;\n  padding: 10px 16px;\n  font: inherit;\n}\n\nbutton {\n  font: inherit;\n  cursor: pointer;\n  border: 0;\n  border-radius: 999px;\n  padding: 10px 20px;\n  background: var(--accent);\n  color: #04202c;\n  font-weight: 600;\n}\n\nbutton:disabled {\n  opacity: 0.55;\n  cursor: not-allowed;\n}\n\nbutton.ghost {\n  background: transparent;\n  color: var(--muted);\n  border: 1px solid var(--line);\n  padding: 6px 14px;\n}\n\nbutton.ghost:hover:not(:disabled) {\n  color: var(--text);\n  border-color: var(--muted);\n}\n\nbutton.mic {\n  width: 44px;\n  height: 44px;\n  padding: 0;\n  display: grid;\n  place-items: center;\n  background: #0e1626;\n  color: var(--accent);\n  border: 1px solid var(--line);\n  flex: none;\n}\n\nbutton.mic[aria-pressed='true'] {\n  background: #7cf0c6;\n  color: #04261b;\n  border-color: #7cf0c6;\n}\n\n:focus-visible {\n  outline: 2px solid var(--accent);\n  outline-offset: 2px;\n}\n\n.side {\n  display: flex;\n  flex-direction: column;\n  gap: 16px;\n}\n\n.panel {\n  padding: 14px 16px;\n}\n\n.panel h2 {\n  margin: 0 0 8px;\n  font-size: 0.8rem;\n  letter-spacing: 0.08em;\n  text-transform: uppercase;\n  color: var(--muted);\n}\n\n.inventory {\n  list-style: none;\n  margin: 0;\n  padding: 0;\n  display: flex;\n  flex-direction: column;\n  gap: 8px;\n}\n\n.inventory li {\n  padding: 8px 10px;\n  border: 1px solid var(--line);\n  border-radius: 10px;\n  background: #0e1626;\n}\n\n.inventory li.empty {\n  color: var(--muted);\n  border-style: dashed;\n}\n\n.inventory li.alert {\n  border-color: var(--alert);\n}\n\n.inventory li.alert.high {\n  border-color: var(--danger);\n}\n\n.inventory li.alert.question {\n  border-color: var(--line);\n}\n\n.inventory small {\n  display: block;\n  color: var(--muted);\n}\n\n.inventory .badge {\n  display: inline-block;\n  font-size: 0.7rem;\n  font-weight: 700;\n  letter-spacing: 0.05em;\n  text-transform: uppercase;\n  border-radius: 999px;\n  padding: 0 8px;\n  margin-bottom: 2px;\n  color: #2b1a00;\n  background: var(--alert);\n}\n\n.inventory li.alert.high .badge {\n  color: #2a0006;\n  background: var(--danger);\n}\n\n.inventory li.alert.question .badge {\n  color: var(--text);\n  background: #2c3956;\n}\n\n@media (max-width: 800px) {\n  .layout {\n    grid-template-columns: 1fr;\n  }\n  .chat {\n    height: 60vh;\n  }\n}\n"
  }
